INSERT INTO ncs_unit (code, subcategory_code, seq, name, level, definition) VALUES
  ('0201020103_24v3', '02010201', 3, '온라인 PR', 3, '온라인 PR은 온라인 매체를 통해 PR 대상자에게 정보를 전달하기 위하여 매체별 콘텐츠를 제작하여 알리는 능력이다.'),
  ('0201020104_24v3', '02010201', 4, '오프라인 PR', 3, '오프라인 PR은 오프라인 매체를 통해 PR 대상자에게 정보를 전달하기 위하여 매체별 홍보물을 제작하여 알리는 능력이다.'),
  ('0201020105_24v3', '02010201', 5, '언론 홍보', 5, '언론 홍보는 조직이 의도하는 이슈를 언론을 통해 긍정적 이미지를 형성할 수 있도록 알리는 능력이다.'),
  ('0201020106_24v3', '02010201', 6, '조직문화 전파', 3, '조직문화 전파는 조직문화를 조직 내외에 전파하기 위하여 전파 현황 파악, 전파계획 수립, 전파 프로그램 실행, 활동결과를 평가하는 능력이다.'),
  ('0201020107_24v3', '02010201', 7, '사회공헌활동', 3, '사회공헌활동은 전략적으로 조직 이미지를 제고하기 위하여 조직의 사회적 책임 활동계획 수립, 실행체계 구축, 프로그램 실행, 활동 평가를 하는 능력이다.'),
  ('0201020108_24v3', '02010201', 8, '위기관리', 6, '위기관리는 조직에 부정적인 영향을 미칠 수 있는 사건을 사전에 예방하고 발생 시 위기로 전개되는 것을 억제하거나 그로 인한 피해를 최소화하기 위하여 커뮤니케이션하는 능력이다.'),
  ('0201020111_24v4', '02010201', 11, 'PR 환경분석', 3, 'PR 환경분석은 효율적인 PR 전략 수립을 위하여 조사한 언론 홍보, 온·오프라인 PR 현황을 분석하는 능력이다.'),
  ('0201020114_24v4', '02010201', 14, 'PR 환경조사', 3, 'PR 환경조사는 조직의 PR 목적을 달성하기 위해 미디어를 활용하여 정보를 수집하고, PR에 적합한 미디어를 조사하는 능력이다.'),
  ('0201020115_24v5', '02010201', 15, 'PR 전략 수립', 5, 'PR 전략 수립은 조직의 PR 목표를 달성하기 위하여 PR 대상별 목표를 설정하며 효과적인 매체를 선정하는 장단기 PR 전략을 수립하는 능력이다.'),
  ('0201020116_24v4', '02010201', 16, 'PR 활동 평가', 4, 'PR 활동 평가란 PR 활동 평가기준 설정, PR 효과분석, 사후관리 실행을 통해 수행한 결과를 평가하는 능력이다.'),
  ('0201020205_24v4', '02010202', 5, '광고 전략 수립', 5, '광고 전략 수립은 광고 환경을 분석하여 광고 목표를 설정하고, 이를 달성하기 위한 콘셉트를 설정하여 매체 전략을 수립한 후, 광고 전략의 효과적 실행을 위한 기획서를 작성할 수 있는 능력이다.'),
  ('0201020206_24v4', '02010202', 6, '광고 제작', 4, '광고 제작이란 광고 목표 달성을 위해 크리에이티브 콘셉트를 설정하고 아이디어를 도출하여 매체에 맞는 콘텐츠를 제작하는 능력이다.'),
  ('0201020207_24v4', '02010202', 7, '광고 집행 관리', 4, '광고 집행 관리란 매체별 광고 실행 계획에 의거하여 매체를 선정·구매하고 광고의 집행과 매체별 모니터링을 실시하는 능력이다.'),
