  ('0403020316_16v2', '04030203', 16, '이러닝운영 결과관리', 6, '이러닝운영 결과관리란 과정운영에 필요한 콘텐츠, 교강사, 시스템, 운영 활동의 성과를 분석하고 개선사항을 관리하여 그 결과를 최종 평가보고서 형태로 작성하는 능력이다.'),
  ('0403020317_16v1', '04030203', 17, '이러닝운영 통합관리', 7, '이러닝운영 통합관리란 이러닝운영에 대한 품질관리를 실시하여 개선방안을 모색하고  사업 진행을 위한 인력과 자원을 관리하며, 사업 진행에서 발생할 수 있는 위험을 인식, 분석, 계획, 평가, 통제할 수 있는 능력이다.'),
  ('0801010101_14v1', '08010101', 1, '문화예술 기획전략 수립', 7, '문화예술 기획전략수립이란 작품을 개발하여 계획하는 활동에 있어 관객 참여의 극대화를 유도할 수 있도록 기획의 방향과 방법을 구상하여 수립하는 능력이다.'),
  ('0801010102_20v2', '08010101', 2, '문화예술 예산관리', 5, '문화예술 예산관리는 문화예술상품의 실행을 위해서 예산을 세우고 집행하며 정산하는 능력이다.'),
  ('0801010103_20v2', '08010101', 3, '문화예술 작품선정', 6, '문화예술 작품선정이란 문화예술 작품의 상품화를 위해서 기획전략에 따라 실행 작품과 예술가를 선정하고 작품의 방향을 제시하는 능력이다.'),
  ('0801010104_20v2', '08010101', 4, '문화예술 실행계획 수립', 5, '문화예술 실행계획 수립이란 문화예술작품을 실행할 수 있도록 인력조직, 실행, 물적·인적 일정을 계획 수립하는 능력이다.'),
  ('0801010105_20v2', '08010101', 5, '문화예술 장소계획 수립', 3, '문화예술 장소계획 수립이란 문화예술기획 전략에 따라 선정된 작품을 효율적으로 실행할 수 있는 적정한 장소를 선정하고 계약하여 사용목적에 적합하게 구성하는 능력이다.'),
  ('0801010106_20v2', '08010101', 6, '문화예술 인력구성', 4, '문화예술 인력구성이란 기획의도에 따라 작품에 참여할 예술가와 스태프 인력을 문화예술 관련 법규를 준수하여 구성하는 능력이다.'),
  ('0801010107_20v2', '08010101', 7, '문화예술 작품실행', 5, '문화예술 작품실행이란 실행 계획에 따라 효율적인 운영이 가능하도록 인력과 연습 과정을 관리하고 실행하는 능력이다.'),
  ('0801010108_20v2', '08010101', 8, '문화예술 홍보관리', 4, '문화예술 홍보관리는 문화예술상품을 홍보하고 집객을 유도하기 위해 환경을 분석하고  목표와 콘셉트를 설정하여 장단기 전략을 수립하고 실행하는 능력이다.'),
  ('0801010109_20v2', '08010101', 9, '문화예술 실행 위기관리', 4, '문화예술 실행 위기관리란 문화예술작품 실행의 안전을 위하여 위기상황별 대처계획 및 안전계획을 수립하고 관계기관 협조체계를 구축하여 비상상황을 관리할 수 있는 능력이다.')
INSERT INTO ncs_unit (code, subcategory_code, seq, name, level, definition) VALUES
  ('0801010110_20v2', '08010101', 10, '문화예술 실행 사후관리', 5, '문화예술 실행 사후관리란 작품실행이 문화예술기획 목적에 부합 되었는지 확인하기 위해 결과를 분석하고 부가판권을 관리함으로써 부가가치를 창출하는 능력이다.'),
  ('0802010106_20v3', '08020101', 6, '프레젠테이션', 5, '프레젠테이션이란 클라이언트의 요구사항과 점검사항을 디자인 개발에 반영하고 시각적 결과물에 적용하여 다양한 시청각 자료를 활용하여 발표하고 협의와 설득하는 능력이다.'),
  ('0802010108_20v2', '08020101', 8, '디자인 제작 관리', 5, '디자인 제작 관리란 완성된 디자인을 데이터 파일로 변환하여 샘플을 확인하고 발주ㆍ감리하는 능력이다.'),
  ('0802010109_20v3', '08020101', 9, '디자인 자료화', 4, '디자인 자료화란 완성된 디자인 결과물을 정리하여 관리하고 결과물에 대한 권리를 보호하기 위하여 지식재산권을 확보하는 능력이다.'),
  ('0802010110_20v3', '08020101', 10, '시각디자인 프로젝트 기획 구상', 5, '시각디자인 프로젝트 기획 구상이란 의뢰된 디자인 프로젝트의 목적, 내용, 일정, 요구사항을 파악하여 전체 디자인 프로세스를 준비하는 능력이다.'),
  ('0802010111_20v3', '08020101', 11, '시각디자인 프로젝트 기획', 6, '시각디자인 프로젝트 기획이란 디자인 프로젝트의 목적, 내용, 일정, 요구사항을 파악하여 전체 디자인 프로세스를 구상하는 능력이다.'),
  ('0802010112_20v4', '08020101', 12, '시각디자인 리서치 조사', 4, '시각디자인 리서치 조사란 프로젝트를 성공적으로 수행하기 위하여 관련 분야에 관한 다양한 자료를 수집, 분류, 분석하여 효과적 디자인 개발을 위한 기초를 마련하고자 조사하는 능력이다.'),
  ('0802010113_20v4', '08020101', 13, '시각디자인 리서치 분석', 4, '시각디자인 리서치 분석이란 프로젝트를 성공적으로 수행하기 위하여 관련 분야에 관한 다양한 자료를 수집, 분류, 조사한 결과를 분석하는 능력이다.'),
  ('0802010114_20v4', '08020101', 14, '시각디자인 전략수립', 6, '시각디자인 전략수립이란 리서치를 통하여 수집?분석된 자료를 바탕으로 요구사항에 적합한 디자인 콘셉트를 도출하고 크리에이티브 전략을 수립하는 능력이다.'),
  ('0802010115_20v4', '08020101', 15, '시각디자인 전략 수립 운용', 7, '시각디자인 전략 수립 운용이란 리서치를 통하여 수집ㆍ분석된 자료를 바탕으로 추출된 디자인 콘셉트 및 크리에이티브 전략을 수립하고, 수립된 전략을 프로젝트의 목표에 맞게 운용하기 위한 능력이다'),
  ('0802010116_20v4', '08020101', 16, '비주얼 아이데이션 구상', 3, '비주얼 아이데이션 구상이란 프로젝트의 디자인 콘셉트에 대한 다양한 생각들을 도출하고 표현하는 능력이다.'),
  ('0802010117_20v4', '08020101', 17, '비주얼 아이데이션 전개', 4, '비주얼 아이데이션 전개란 프로젝트의 디자인 콘셉트에 대한 효과적인 생각들을 시각적으로 표현하고 전개하는 능력이다.'),
  ('0802010118_20v4', '08020101', 18, '비주얼 아이데이션 적용', 5, '비주얼 아이데이션 적용이란 프로젝트의 디자인 콘셉트를 구체화하여 시각적으로 표현하고 적용하는 능력이다.'),
  ('0802010119_20v3', '08020101', 19, '시안 디자인 개발 기초', 3, '시안 디자인 개발 기초란 각종 디자인 작업 도구 및 컴퓨터 프로그램을 사용하여 프로젝트의 콘셉트에 맞는 여러 가지 디자인 시안을 제안하고 제작하는 능력이다.'),
  ('0802010120_20v3', '08020101', 20, '시안 디자인 개발 응용', 4, '시안 디자인 개발 응용이란 각종 디자인 작업 도구 및 컴퓨터 프로그램을 사용하여 프로젝트의 콘셉트에 맞는 여러 가지 디자인 시안을 응용하여 제작하는 능력이다.'),
  ('0802010121_20v3', '08020101', 21, '시안 디자인 개발 심화', 5, '시안 디자인 개발 심화란 각종 디자인 작업 도구 및 컴퓨터 프로그램을 사용하여 프로젝트의 콘셉트에 맞는 여러 가지 디자인 시안의 완성도를 높이는 능력이다.'),
  ('0802010122_20v4', '08020101', 22, '최종 디자인 실행', 5, '최종디자인 실행이란 선정된 시안에 필요한 일러스트레이션, 사진촬영, 카피라이팅, 타이포그래피, 레이아웃, 색상 등을 완성하고, 그에 따른 어플리케이션 디자인까지 개발하는 능력이다.'),
  ('0802010123_20v4', '08020101', 23, '디자인 개발 완료', 5, '디자인 개발 완료란 선정된 시안에 필요한 일러스트레이션, 사진촬영, 카피라이팅, 타이포그래피, 레이아웃, 색상 등을 완성하고, 그에 따른 어플리케이션 디자인까지 완료하여 피드백을 반영하는 능력이다.'),
  ('0802010206_16v2', '08020102', 6, '모형 제작', 4, '모형 제작이란 2D 또는 3D 컴퓨터모델링이나 도면 작업 후 최종디자인을 확정하는 단계로서 다양한 제작 기법을 통해 소재, 색상, 구조, 동작 등을 확인하고, 기구 설계, 금형 설계 및 마케팅 프로모션을 위한 모형을 제작 및 관리하는 능력이다.'),
  ('0802010207_13v1', '08020102', 7, '양산 관리', 5, '양산 관리란 최종 안으로 결정된 디자인 안에 대하여 지식재산권을 확보하고, 제품을 생산할 수 있도록 디자인 사양서를 발행, 인증검사, 한도 견본 승인과 같은 관리 능력하는 능력이다.'),
  ('0802010209_16v2', '08020102', 9, '제품디자인 프로젝트 기획 계획수립', 5, '제품디자인 프로젝트 기획 계획 수립은 프로젝트 수행에 앞서 클라이언트의 요구(needs), 범위(scope), 프로젝트 결과물(output)에 대해 정확하게 이해하고 수준을 파악하여 이를 기반으로 프로젝트를 수행하기 위한 상세 기획안을 수립, 명시하는 능력이다.'),
  ('0802010210_16v2', '08020102', 10, '제품디자인 프로젝트 기획 제안발표', 7, '제품디자인 프로젝트 기획 제안 발표는 수립된 기획서 및 방향을 바탕으로 제안서(제안내용, 견적서, 일정 등) 작성을 위한 준비를 하고, 프로젝트를 계약하는 능력이다.'),
  ('0802010211_16v2', '08020102', 11, '제품디자인 리서치 기초', 4, '제품디자인 리서치 기초란 전반적인 제품특성에 대한 시장 환경의 이해를 바탕으로 경쟁사ㆍ경쟁제품의 현황, 시장 환경, 디자인 트렌드 등을 파악하고 조사하여 분석 자료의 기본을 분류하는 능력이다.'),
  ('0802010212_16v2', '08020102', 12, '제품디자인 리서치 분석', 5, '제품디자인 리서치 분석이란 전반적인 제품특성에 대한 시장 환경의 이해를 바탕으로 경쟁사ㆍ경쟁제품에 대한 분석, 디자인 트렌드의 진화방향 파악, 사용자 분석을 거쳐 구체적 개발 방향을 도출해낼 수 있도록 기초자료를 확보하는 능력이다.'),
  ('0802010213_16v2', '08020102', 13, '제품디자인 전략수립 방향설정', 5, '제품디자인 전략 수립 방향 설정이란 ‘제품디자인 리서치’의 분석 결과를 종합하여 제품 개발에 필요한 차별화 요소를 결정하여 제품 전략을 수립하는 능력이다.'),
  ('0802010214_16v2', '08020102', 14, '제품디자인 전략수립 콘셉트 구체화', 7, '제품디자인 전략 수립 콘셉트 구체화란 ‘제품디자인 리서치’의 분석 결과를 종합하여 제품 구현에 필요한 차별화 요소와 경쟁 포인트 등 구체적 사양을 결정하여, 다음 단계인 ‘디자인 아이디어 발상’의 준거로 활용하는 능력이다.'),
