  ('1001010102_14v1', '10010101', 2, '영업 내부환경분석', 4, '영업 내부 환경 분석이란 자사의 영업상의 강점과 약점을 파악하기 위하여 내부환경 분석계획을 수립하여 내부 상황, 상품에 관한 내부환경 분석 보고서를 작성할 수 있는 능력이다.'),
  ('1001010103_20v2', '10010101', 3, '영업 전략수립', 5, '영업 전략수립이란 영업 환경분석 결과를 바탕으로 영업 전략 방향과 영업 목표를 설정하여 실행항목을 정의하고 운영계획을 수립하는 능력이다.'),
  ('1001010104_20v2', '10010101', 4, '영업 고객발굴', 3, '영업 고객발굴이란 고객 상담 계획을 수립하고 다양한 고객 상담 수단을 통하여 고객을 발굴하는 능력이다.'),
  ('1001010105_20v2', '10010101', 5, '영업 제안', 3, '영업 제안이란 계약 체결을 위하여 고객이 요구하는 조건에 맞는 상품을 제안하는 능력이다.'),
  ('1001010106_20v2', '10010101', 6, '영업 계약체결관리', 3, '영업 계약체결관리란 고객과의 협상을 통해 계약을 성공적으로 체결하기 위한 과정을 관리하는 능력이다.'),
  ('1001010107_20v2', '10010101', 7, '영업 계약이행관리', 3, '영업 계약이행관리란 계약 사항이 원활히 이행될 수 있도록 관리하는 능력이다.'),
  ('1001010108_20v2', '10010101', 8, '영업 성과관리', 5, '영업 성과관리란 지속적인 영업 성과를 창출하기 위하여 영업 실적을 평가하고 관리하는 능력이다.'),
  ('1001010109_20v2', '10010101', 9, '영업 고객불만관리', 3, '영업 고객불만관리란 고객 이탈을 방지하고 상품을 개선하기 위하여 불만 사항 해결 과정을 관리하는 능력이다.'),
  ('1001010110_20v2', '10010101', 10, '영업 고객유지관리', 3, '영업 고객유지관리란 고객의 이탈을 방지하고 충성고객을 확보하기 위하여 입수된 데이터를 기준으로 고객유지 전략을 수립하고 실행하는 능력이다.'),
  ('1001010111_20v2', '10010101', 11, '영업 환경분석', 4, '영업 환경분석이란 영업 전략 수립을 위하여 영업 환경 정보를 수집하고 경쟁사 대비 자사 상품을 분석하는 능력이다.'),
  ('1001010201_20v2', '10010102', 1, '해외시장 조사', 4, '해외시장 조사란 시장 동향 파악을 위하여 조사 계획을 수립하고, 환경을 분석한 것을 토대로 해외시장 조사 보고서를 작성하는 능력이다.'),
  ('1001010202_20v2', '10010102', 2, '해외영업 상품 분석', 4, '해외영업 상품 분석이란 해외 시장에 판매할 상품의 영업 전략을 수립하기 위하여 상품의 각종 특성 및 원가, 사업성을 분석하여 합리적인 의사결정을 위한 상품 분석보고서를 작성하는 능력이다.'),
  ('1001010203_20v2', '10010102', 3, '해외마케팅 전략수립', 6, '해외마케팅 전략 수립이란 상품의 해외 판매를 위하여 목표시장 진입전략, 시장 유지전략, 경쟁 전략 및 각종 위기관리계획을 수립하는 능력이다.'),
  ('1001010204_20v2', '10010102', 4, '해외 잠재고객 발굴', 3, '해외 잠재고객 발굴이란 목표시장의 해외고객을 확보하기 위하여 다양한 정보를 활용하여 잠재고객을 탐색하고, 해외 전시회 및 상담회 등 각종 홍보 행사에 참가하며, 온라인 또는 오프라인을 통해 잠재고객을 발굴하는 능력이다.'),
  ('1001010205_20v2', '10010102', 5, '해외거래 제안', 3, '해외거래 제안이란 거래가 이루어질 수 있도록 상품소개서를 작성하고, 잠재 고객의 인콰이어리를 검토하여 거래를 제안하는 능력이다.'),
  ('1001010206_20v2', '10010102', 6, '해외고객 협상', 5, '해외고객 협상이란 계약을 체결하기 전 단계로 고객과의 합의점을 도출하기 위하여 계약 조건에 대한 협상전략을 수립하고, 고객에 대한 의전을 수행하여 협상을 실행하는 능력이다.'),
  ('1001010207_14v1', '10010102', 7, '국제계약체결', 5, '국제계약 체결이란 협상을 통해 합의된 내용을 공식적으로 확정하기 위하여 계약조건을 검토하고, 계약서를 작성하여 계약을 체결하고, 통지하는 능력이다.'),
  ('1001010208_20v2', '10010102', 8, '해외영업 계약 이행 관리', 2, '계약 이행 관리란 체결된 계약의 이행을 위하여 대금 결제를 관리하고, 계약 상품의 품질 및 사양을 관리하며, 상품의 선적 및 납기를 지속적으로 관리하는 능력이다.'),
  ('1001010209_14v1', '10010102', 9, '해외 클레임 처리', 4, '클레임 처리란 고객이 제기한 클레임을 해결하기 위하여 클레임의 내용을 검토, 분석하고 해결책을 준비하여, 고객과 협상하는 능력이다.'),
  ('1001010210_20v2', '10010102', 10, '해외고객 관리', 5, '해외고객 관리란 고객과의 지속적인 영업관계를 유지하기 위하여 해외고객의 요구를 분석하고, 평가하는 능력이다.'),
  ('1003010202_16v2', '10030102', 2, '사업기획', 6, '이 능력단위는 기업이 가진 전략적인 가치를 높이기 위해 적절한 상품과 서비스를 시장조사를 통하여 구매대상자가 원하는 상품의 개발전략을 수립하고 그에 따른 마케팅 계획과 판매계획, 투자계획을 수립할 수 있는 능력이다.'),
  ('1003010203_16v2', '10030102', 3, '사이트 기획', 5, '이 능력단위는 사이트 개발계획 수립, 사이트 디자인, 사이트 설계 등의 작업을 통하여 전자상거래 사이트의 종합적인 기획안을 수립하는 능력이다.'),
  ('1003010204_16v2', '10030102', 4, '사이트 구축', 4, '이 능력단위는 사이트 기획단계에 따라 확정된 전자상거래 사이트를 구현하고 상품 판매에 관련된 콘텐츠를 온라인상의 시스템에 맞게 변환하여 기초적인 데이터베이스를 구축하고 이를 자사, 타사 사이트에서 판매 가능하도록 체계화하는 능력이다.'),
  ('1003010205_16v2', '10030102', 5, '사이트 운영', 3, '이 능력단위는 제공되는 전자 상거래 서비스의 정확성과 신뢰성을 증진시키기 위해 시스템 관리 및 상품 관리, 외부시스템 관리 및 사이트 유지보수를 수행하고 이에 기반하여 사이트를 운영 및 관리 하는 능력이다.'),
  ('1003010207_16v2', '10030102', 7, '판매관리', 3, '이 능력단위는 상품을 주문 처리하고, 대금을 결재관리하며, 상품의 배송관리와 교환/반품관리, 재고관리와 판매정보를 관리 하는 능력이다.'),
  ('1003010208_13v1', '10030102', 8, '고객관리', 3, '이 능력단위는 고객에 대하여 고객DB관리하고, 고객의 정보보안, 고객등급을 관리하며, 고객으로부터 받은 클레임에 대한 관리를 하는 능력이다.'),
  ('1003010209_13v1', '10030102', 9, '사후관리', 3, '이 능력단위는 전자상거래 사이트를 운영 중에 고객이 작성한 판매후기 관리와 고객 만족도를 조사하여 매출확대를 위한 대책을 수립하는 등 판매실적을 관리하고, 일정기간이 경과한 후 전자상거래 사업성과를 분석하여 대책을 수립할 수 있는 능력이다.'),
  ('1003010210_16v2', '10030102', 10, '시장환경분석', 5, '이 능력단위는 시장환경, 고객요구사항, 경쟁사현황 등의 현황분석을 통하여 전자상거래 사업의 내외부 환경을 분석하는 능력이다.'),
  ('1003010211_16v2', '10030102', 11, '기술동향분석', 5, '이 능력단위는 관련 사례를 분석하고 기술 동향을 분석하는 등 전자상거래 사업의 내외부 환경을 분석하는 능력이다.'),
  ('1003010212_16v2', '10030102', 12, '마케팅 관리', 5, '이 능력단위는 전자상거래를 통해 콘텐츠 전략을 수립한 후 마케팅을 실행하고 뉴미디어마케팅과 연동하는 능력이다.'),
  ('1003010213_16v2', '10030102', 13, '마케팅 성과측정과 활용', 5, '이 능력단위는 전자상거래를 할 때 수립된 마케팅 기법에 따라 성과 측정에 필요한 적절한 성과측정 계획을 수립하고 그 결과를 활용하는 능력이다.'),
  ('1201010101_21v5', '12010101', 1, '미용업 안전위생 관리', 2, '미용업 안전위생 관리란 고객에게 안전하고 위생적인 서비스를 제공하기 위해 공중위생관리법을 기반으로 미용사 및 미용업소의 내？외부 환경을 관리하는 능력이다.'),
  ('1201010112_21v5', '12010101', 12, '두피·모발 관리', 3, '두피·모발관리란 고객의 두피·모발 상태에 따라 기기와 제품을 사용하여 두피의 혈액순환을 촉진하고 모발에 영양분을 공급하여 두피와 모발을 탄력있게 관리하는 능력이다.')
INSERT INTO ncs_unit (code, subcategory_code, seq, name, level, definition) VALUES
  ('1201010113_21v4', '12010101', 13, '헤어미용 전문제품 사용', 3, '헤어미용 전문제품 사용이란 고객의 두피？모발 상태 및 서비스 목적에 따라 제품을 선정하고 홈케어 제품을 고객에게 추천하는 능력이다.'),
  ('1201010116_21v6', '12010101', 16, '미용고객응대', 2, '미용고객응대란 미용서비스 시술을 받기 위한 고객에게 접점 상황별 서비스를 제공하는 능력이다.'),
  ('1201010120_19v5', '12010101', 20, '베이직 헤어펌', 2, '베이직 헤어펌이란 모발에 펌제를 도포하고 로드로 와인딩하여 모발을 웨이브형태로 변화시킬 수 있는 능력이다.'),
  ('1201010121_19v5', '12010101', 21, '롤 헤어펌', 2, '롤 헤어펌이란 모발에 펌제를 도포하고 롤을 사용한 와인딩 기법으로 모발을 C컬 형태로 변화시킬 수 있는 능력이다.'),
  ('1201010122_19v5', '12010101', 22, '매직스트레이트 헤어펌', 2, '매직스트레이트 헤어펌이란 모발에 펌제를 도포하고 플랫 형태의 매직기를 사용하여 모발을 스트레이트 형태로 변화시킬 수 있는 능력이다.'),
  ('1201010123_17v4', '12010101', 23, '기초 드라이', 2, '기초 드라이란 블로우 드라이어, 헤어 아이론, 헤어브러시 등의 기기 및 도구를 이용하여 모발을 스트레이트 또는 C컬 형태로 연출하는 능력이다.'),
  ('1201010124_17v4', '12010101', 24, '헤어컬러 분석', 2, '헤어컬러 분석이란 헤어피스에 염모제와 탈색제를 사용하여 다양한 색으로 표현된 헤어 스와치로 차트를 완성하는 능력이다.'),
  ('1201010125_21v6', '12010101', 25, '베이직 헤어컬러', 2, '베이직 헤어컬러란 블리치 레벨 차트와 컬러 차트에서 고객이 선택한 컬러의 염모제를 모발에 원터치 또는 투 터치 등의 도포법을 적용하여 모발의 색을 변화시키는 능력이다.'),
  ('1201010126_21v5', '12010101', 26, '그레이 헤어컬러', 3, '그레이 헤어컬러란 백모의 비율을 고려하여 백모 커버 목적에 적합한 염모제를 선택 후다양한 도포기법을 사용하여 백모를 커버하는 능력이다.'),
  ('1201010128_21v5', '12010101', 28, '원랭스 헤어커트', 2, '원랭스 헤어커트란 층이 없는 형태의 헤어커트 스타일로 두상의 모든 모발을 동일선상 에서 커트하는 능력이다.'),
  ('1201010129_17v4', '12010101', 29, '고객관계 관리', 3, '고객관계 관리란 고객의 재방문 및 브랜드 충성도를 높이기 위해 고객의 정보를 수집하여 관리하고 활용하는 능력이다.'),
