  ('1201010459_23v1', '12010104', 59, '트렌드 인조 네일', 3, '트렌드 인조 네일이란 새로운 방법으로 연장하기 위해 네일 팁과 폴리머 젤을 활용하여 조형하는 능력이다.'),
  ('1203010101_22v3', '12030101', 1, '여행상품 시장조사', 4, '여행상품 시장조사란 여행상품 개발의 기초자료로 사용하기 위하여 시장 환경, 수요자 조사, 경쟁상품을 분석하는 능력이다.'),
  ('1203010102_22v2', '12030101', 2, '여행상품 상품화 검토', 5, '여행상품 상품화 검토란 여행상품의 적합성을 검토하기 위하여 여행상품의 수익성, 모객능력, 지속성을 분석하는 능력이다.'),
  ('1203010103_22v3', '12030101', 3, '여행상품 원가분석', 4, '여행상품 원가분석이란 여행상품의 원가우위를 확보하기 위하여 교통편, 숙박시설(기존대로), 관광자원의 원가를 분석하는 능력이다.'),
  ('1203010104_22v3', '12030101', 4, '여행샘플상품 구성', 3, '여행샘플상품 구성이란 고객의 여행욕구를 충족시키기 위하여 가격별 상품, 시즌별 상품, 대상별 상품을 구성하는 능력이다.'),
  ('1203010105_22v3', '12030101', 5, '여행상품 샘플투어', 3, '여행상품 샘플 투어란 여행상품 출시 전 보완사항을 파악하기 위하여 서베이 투어, 모니터링 투어, 팸 투어를 수행하는 능력이다.'),
  ('1203010107_22v3', '12030101', 7, '여행상품개발 자원관리', 6, '여행상품개발 자원관리란 효율적인 상품개발을 위하여 인적자원을 구성하고, 예산을 편성하여, 물적 자원과 네트워크를 구축하는 능력이다.'),
  ('1203010108_22v2', '12030101', 8, '여행상품 출시', 5, '여행상품 출시란 여행상품을 판매하기 위하여 판매가격을 확정하고, 상품 출시, 상품정보를 구축을 하는 능력이다.'),
  ('1203010109_22v2', '12030101', 9, '여행상품 관리', 5, '여행상품 관리란 여행상품의 원활한 판매를 위하여 상품인증을 관리하고, 상품 매뉴얼을 작성하며, 계약 관리 업무를 수행하는 능력이다.'),
  ('1203010110_13v1', '12030101', 10, '여행상품 교육훈련', 5, '여행상품 교육훈련이란 교육훈련 계획을 수립하고, 교육 자료를 구축하여, 교육훈련을 실시？평가하는 능력이다.'),
  ('1203010111_16v1', '12030101', 11, '여행상품 시장조사 지원', 2, '여행상품 시장조사 지원이란 시장환경 분석을 지원하고 수요자 조사, 경쟁상품 자료수집을 수행하는 능력이다.'),
  ('1203010112_16v1', '12030101', 12, '여행상품 원가조사', 2, '여행상품 원가조사란 교통요소, 숙박요소, 관광자원요소를 조사하는 능력이다.'),
  ('1203010113_22v3', '12030101', 13, '여행상품 STP전략', 4, '여행상품 STP전략이란 시장조사를 바탕으로 여행상품개발의 성공확률을 높이기 위하여 시장을 세분화하고, 목표시장을 선정하며, 시장에서 자사(상품) 포지셔닝 하는 능력이다.'),
  ('1203010114_22v3', '12030101', 14, '여행상품 마케팅 믹스', 4, '여행상품 마케팅 믹스란 여행상품의 효율적 판매를 위하여 여행상품 마케팅 전략에 따라 상품전략, 가격 전략, 유통전략, 촉진전략, 서비스마케팅전략을 수립하는 능력이다.'),
  ('1203010115_16v1', '12030101', 15, '여행상품 교육훈련 지원', 2, '여행상품 교육훈련 지원이란 교육훈련 계획수립, 교육자료 작성, 교육운영을 지원하는 능력이다.'),
  ('1203010201_13v1', '12030102', 1, '고객응대', 3, '고객 응대란 전화, 방문, 인터넷 등으로 응대하는 능력이다.'),
  ('1203010202_13v1', '12030102', 2, '상품 추천', 3, '상품 추천이란 고객 정보·욕구를 파악하여 상품을 추천하는 능력이다.'),
  ('1203010203_22v3', '12030102', 3, '여행상품상담 교육', 5, '여행상품상담 교육이란 여행상담원의 여행상품상담 업무 수행을 위해 상품정보 파악, 상품상담 매뉴얼 작성, 상품 상담 교육을 할 수 있는 능력이다.'),
  ('1203010204_16v2', '12030102', 4, '상품설명자료 작성', 3, '상담 자료 작성이란 상담자료를 수집하고 작성한 후 전달하는 능력이다.'),
  ('1203010205_13v1', '12030102', 5, '상품 설명', 4, '상품 설명이란 상품 설명 방법을 선택한 후 상품을 설명하고 상품 설명 결과를 활용하는 능력이다.'),
  ('1203010206_13v1', '12030102', 6, '상담 고객관리', 3, '상담 고객 관리란 부가 상품 정보를 제공하고 네트워크를 활용하여 고객을 관리하는 능력이다.'),
  ('1203010207_22v3', '12030102', 7, '여행요금 상담', 4, '여행요금 상담이란 고객의 요청에 따라 상품 판매 가격 결정을 위하여 원가표를 작성하고 여행 요금을 산출하여 상담하는 능력이다.'),
  ('1203010208_16v2', '12030102', 8, '교통편예약', 4, '교통편 예약이란 항공·육상·해상 교통편 여객 예약을 수행하는 능력이다.'),
  ('1203010209_22v2', '12030102', 9, '여행 상품 계약', 3, '여행 상품 계약이란 고객에게 사전 합의한 상품을 제공하기 위하여 계약 서류를 작성한 후 계약을 체결하고 최종 결제 내용을 확인하는 능력이다.'),
  ('1203010210_22v3', '12030102', 10, '여행 고객 관리', 4, '여행 고객 관리란 여행상품 계약이 완료된 고객의 원활한 여행과 사후 관리를 위하여 여행 정보 자료를 제공하고 여행 후 사후 관리를 하며 재방문 고객을 창출하는 능력이다.'),
  ('1203010211_16v1', '12030102', 11, '여행상품상담 교육 지원', 2, '여행상품상담 교육 지원이란 상품정보파악, 상품상담 매뉴얼 작성, 상품 상담 교육을 지원하는 능력이다.'),
  ('1203010212_16v1', '12030102', 12, '교통편 조회', 2, '교통편 조회란 항공·육상·해상 교통편 여객 예약을 조회하는 능력이다.'),
  ('1203010213_22v2', '12030102', 13, '교통편 발권', 3, '교통편 발권이란 항공·육상·해상 교통편 여객의 여행 이동 수단의 편의를 제공하기 위하여 해당 교통편 여객 발권을 수행하는 능력이다.'),
  ('1203010214_22v2', '12030102', 14, '지상수배', 3, '지상수배란 고객이 계약한 여행상품의 계약 의무이행을 위하여 여행 목적지의 숙박시설, 현지 교통편, 식당시설, 관광지를 수배하는 능력이다.'),
  ('1203010215_16v1', '12030102', 15, '여행서류 확인 지원', 2, '여행서류확인 지원이란 여권, 비자, 출입국, 보험 서류 등의 확인을 지원하는 능력이다.'),
  ('1203010216_22v2', '12030102', 16, '여행서류 확인', 2, '여행서류 확인이란 고객의 원활한 해외여행을 준비하기 위하여 여권, 비자, 출입국, 보험 서류를 확인하는 능력이다.')
INSERT INTO ncs_unit (code, subcategory_code, seq, name, level, definition) VALUES
  ('1203010217_22v2', '12030102', 17, '고객 응대 서비스', 2, '고객 응대 서비스란 여행사의 신규 고객을 유치하기 위하여 고객 문의에 응대하고, 고객의 수요를 정확히 파악하여 상품을 추천하고, 상담 고객의 정보를 관리하여 상담 후 고객을 유치하는 능력이다.'),
  ('1203010218_22v3', '12030102', 18, '여행 상품 설명', 3, '여행 상품 설명이란 고객의 요구에 부합하는 상품을 제공하기 위하여 상품 설명 자료를 수집하고 작성하고 설명한 후 상담 결과를 활용하는 능력이다.'),
  ('1203010219_22v3', '12030102', 19, '교통편 조회 예약', 2, '교통편 조회 예약이란 항공·육상·해상 교통편 여객의 여행 이동 수단의 편의를 제공하기 위하여 여행 관련 교통편 조회, 예약을 수행하는 능력이다.'),
  ('1203030101_23v3', '12030301', 1, '회의 유치', 8, '회의 유치란 국·내외 유치 대상 회의를 선정 하고 유치 전략을 수립, 유치 신청서 작성 및 현장조사(site inspection), 유치 활동을 실시하여 회의를 유치하는 능력이다.'),
  ('1203030102_23v3', '12030301', 2, '신규 회의 개발', 7, '신규회의 개발이란 개발대상회의 파악하고 개발타당성 분석, 기본계획 수립, 회의 조직운영체계 구성을 통해 새로운 회의를 개발하는 능력이다.'),
  ('1203030103_23v3', '12030301', 3, '회의 개최 기획', 7, '회의개최 기획이란 회의 유치 또는 개발된 회의의 개최를 목적으로 환경 분석을 통해 목표를 수립하고 회의주제를 도출하여 기획안을 작성하여 발표하는 능력이다.'),
  ('1203030104_23v3', '12030301', 4, '회의 예산 관리', 6, '회의 예산 관리란 사전에 회의 수입과 지출항목을 파악하여 제안 예산 계획을 수립하고, 회의 확정 후 수입 및 지출 관리 방안 수립, 집행, 정산 관련 제반업무를 수행·관리하는 능력이다.'),
  ('1203030105_23v3', '12030301', 5, '회의 후원 유치', 6, '회의 후원 유치란 후원 대상을 발굴하여 후원자 혜택을 개발하고, 후원 유치 제안서 제작, 텔레마케팅, 직접방문을 통해 현물이나 재정적 후원을 획득하는 능력이다.'),
  ('1203030106_23v3', '12030301', 6, '회의 프로그램 설계', 5, '회의 프로그램 설계란 회의 프로그램 구성 내용에 따라 회의 운영방식, 프로그램 편성표를 결정하고 프로그램 콘텐츠로서 발표자료 접수와 연사섭외를 진행하는 능력이다.'),
  ('1203030110_23v3', '12030301', 10, '회의 인력 관리', 3, '회의 인력관리란 원활한 현장운영을 위해 현장인력을 모집하고 선발하며 교육하고 운영하며 평가 업무를 진행하는 능력이다.'),
  ('1203030111_23v3', '12030301', 11, '회의 현장 조성', 4, '회의 현장 조성이란 회의 시설 선정에서부터 회의실을 조성하고, 장비 및 시스템을 구축하고 운영하며, 유지와 보수 업무를 통해 회의장 물자를 관리하는 능력이다.'),
  ('1203030112_23v2', '12030301', 12, '회의 위기 관리', 5, '회의 위기관리란 회의 안전을 보장하기 위해 소방, 의료, 치안, 정보보안과 관련된 위기상황 대처 계획을 수립하고 이에 따라 관계기관 협조 체계를 구축하고, 점검 및 현장 관리를 하는 능력이다.'),
  ('1203030113_23v3', '12030301', 13, '회의 사후 관리', 3, '회의 사후 관리란 회의 평가계획 수립하고, 성과조사와 분석을 실시하며 결과 보고를 통해 회의 목적이 달성되었는지 평가하고 차기년도 계획에 반영하는 능력이다.'),
  ('1203030114_17v3', '12030301', 14, '회의 등록 및 숙박 관리', 3, '회의 등록 및 숙박 관리란 참가자의 제반 회의 참가활동을 지원 및 관리하기 위한 것으로 등록을 접수받고 동선을 관리하고 숙박예약을 받으며 관리를 진행하는 능력이다.'),
  ('1203030115_23v4', '12030301', 15, '의전·수송·관광·식음료 관리', 3, '의전·수송·관광·식음료 관리란 참가자의 의전관리를 실행하고, 관광 및 수송을 실시하고 식음료 관리를 진행하는 능력이다.'),
