  ('2001020208_23v5', '20010202', 8, '정보시스템 이행', 5, '정보시스템 이행이란 개발자 환경에서 개발한 결과물을 운영 환경에 설치하고, 사용자 요구사항과 최종적으로 일치하는지에 대해 승인을 얻어 응용소프트웨어 결과물을 사용자에게 전달하여 인계하고 시스템을 운영할 수 있도록 교육하고 지원하는 능력이다.'),
  ('2001020209_23v6', '20010202', 9, '제품소프트웨어 패키징', 5, '제품소프트웨어 패키징이란 개발이 완료된 제품소프트웨어를 고객에게 전달하기 위한 형태로 패키징하고, 설치와 사용에 필요한 제반 절차 및 환경 등 전체 내용을 포함하는 매뉴얼을 작성하며, 제품소프트웨어에 대한 패치 개발과 업그레이드를 위해 버전관리를 수행하는 능력이다.'),
  ('2001020211_23v6', '20010202', 11, '서버프로그램 구현', 5, '서버프로그램 구현이란 애플리케이션 설계를 기반으로 개발에 필요한 환경을 구성하고, 프로그래밍 언어와 도구를 활용하여 공통모듈, 업무프로그램과 배치 프로그램을 구현하는 능력이다.'),
  ('2001020212_23v6', '20010202', 12, '인터페이스 구현', 5, '인터페이스 구현이란 인터페이스 설계서를 확인하고, 인터페이스 설계서에 따라 기능을 구현하고 검증하는 능력이다.'),
  ('2001020214_23v6', '20010202', 14, '애플리케이션 배포', 3, '애플리케이션 배포란 애플리케이션 배포 환경을 구성하고, 구현이 완료된 애플리케이션의 소스 검증 후 빌드하여 운영 환경에 배포하는 능력이다.'),
  ('2001020217_23v6', '20010202', 17, '애플리케이션 리팩토링', 6, '애플리케이션 리팩토링이란 소스코드가 수행하는 기능을 유지하면서 코드 가독성 및 잠재적 결함을 제거하도록 코드를 개선하는 능력이다.'),
  ('2001020218_23v6', '20010202', 18, '인터페이스 설계', 6, '인터페이스 설계란 응용소프트웨어 개발을 위해 정의된 시스템 인터페이스 요구사항을 확인하고 인터페이스 대상을 식별하여 인터페이스를 설계하는 능력이다.'),
  ('2001020219_23v6', '20010202', 19, '애플리케이션 요구사항 분석', 7, '애플리케이션 요구사항 분석이란 구현하고자 하는 애플리케이션의 요구사항을 도출,  분석, 명세화 및 요구사항 검증을 수행하는 능력이다.'),
  ('2001020220_23v3', '20010202', 20, '기능 모델링', 6, '기능 모델링이란 애플리케이션 요구사항에 의해 도출, 분석된 내용을 애플리케이션의 기능으로 명세화하여 요구사항을 검증하고 소프트웨어 개발범위를 확정하는 능력이다.'),
  ('2001020221_23v6', '20010202', 21, '애플리케이션 설계', 6, '애플리케이션 설계란 요구사항 확인을 통한 상세 분석 결과, 소프트웨어 아키텍처 가이드라인 및 소프트웨어 아키텍처 산출물에 의거하여 이에 따른 애플리케이션 구현을 수행하기 위해 공통모듈 설계, 타 시스템 연동에 대하여 상세 설계하는 능력이다.'),
  ('2001020222_23v6', '20010202', 22, '정적모델 설계', 6, '정적모델 설계란 요구사항 확인을 통한 상세 분석 결과, 소프트웨어 아키텍처 가이드라인 및 소프트웨어 아키텍처 산출물에 의거하여 애플리케이션 구현을 위한 정적모델을 설계하고 검증하는 능력이다.'),
  ('2001020223_23v6', '20010202', 23, '동적모델 설계', 6, '동적모델 설계란 요구사항 확인을 통한 상세 분석 결과, 소프트웨어 아키텍처 가이드라인 및 소프트웨어 아키텍처 산출물에 의거하여 애플리케이션 구현을 위한 동적모델을 설계하고 검증하는 능력이다.'),
  ('2001020224_23v6', '20010202', 24, '화면 설계', 5, '화면 설계란 요구사항분석 단계에서 파악된 화면에 대한 요구사항을 소프트웨어 아키텍처 단계에서 정의된 구현 지침 및 UI/UX 엔지니어가 제시한 UI표준과 지침에 따라 화면을 설계하는 능력이다.'),
  ('2001020225_23v6', '20010202', 25, '화면 구현', 3, '화면 구현이란 UI 요구사항을 확인하여 설계한 UI 설계를 기반으로 화면을 구현하는 능력이다.'),
  ('2001020226_23v6', '20010202', 26, '애플리케이션 테스트 관리', 5, '애플리케이션 테스트 관리란 요구사항대로 응용소프트웨어가 구현되었는지를 검증하기 위해서 테스트케이스를 작성하고 개발자 통합 테스트를 수행하여 애플리케이션의 성능을 개선하는 능력이다.'),
  ('2001020227_23v6', '20010202', 27, '애플리케이션 테스트 수행', 3, '애플리케이션 테스트 수행이란 요구사항대로 응용소프트웨어가 구현되었는지를 검증하기 위해서 분석된 테스트 케이스에 따라 테스트를 수행하고 결함을 조치하는 능력이다.'),
  ('2001020228_23v6', '20010202', 28, '소프트웨어공학 활용', 6, '소프트웨어공학 활용이란 응용 소프트웨어 개발과 프로세스 적용 활동의 관련된 지식을  소프트웨어의 완전성을 보장하고, 소프트웨어 품질을 평가하기 위해 CASE 도구와 형상관리를 통해 소프트웨어 공학 기술을 적용하는 능력이다.'),
  ('2001020229_23v6', '20010202', 29, '소프트웨어개발 방법론 활용', 6, '소프트웨어개발방법론 활용이란 응용소프트웨어 특성에 따라 정형화된 개발방법론을 선정하고, 프로젝트 특성에 맞도록 테일러링 하여 응용소프트웨어 개발에 활용하는 능력이다.'),
  ('2001020230_23v5', '20010202', 30, '프로그래밍 언어 응용', 3, '프로그래밍 언어 응용이란 응용소프트웨어 개발에 사용되는 프로그래밍 언어의 특징과 라이브러리를 활용하여 기본 응용소프트웨어를 구현하는 능력이다.'),
  ('2001020231_23v5', '20010202', 31, '프로그래밍 언어 활용', 2, '프로그래밍 언어 활용이랑 응용소프트웨어 개발에 사용되는 프로그래밍 언어의 기본문법을 활용하여 기본 응용소프트웨어를 구현하는 능력이다.'),
  ('2001020232_23v5', '20010202', 32, '응용SW 기초 기술 활용', 3, '응용SW 기초 기술 활용이란 응용소프트웨어 개발을 위하여 네트워크, 미들웨어, 데이터베이스의 기초 기술을 적용하는 능력이다.')
INSERT INTO ncs_unit (code, subcategory_code, seq, name, level, definition) VALUES
  ('2001020233_23v5', '20010202', 33, '개발자 환경 구축', 2, '개발자 환경 구축이란 응용소프트웨어 개발을 위하여 운영체제의 기초 기술을 적용하여 응용소프트웨어 개발에 필요한 개발자 환경을 구축하는 능력이다.'),
  ('2001020234_23v2', '20010202', 34, '개발 환경 운영 지원', 2, '개발 환경 운영 지원이랑 응용소프트웨어 개발을 위하여 구축된 개발 환경을 백업·복원하고, 소스코드를 관리하는 능력이다.'),
  ('2001020235_23v1', '20010202', 35, '자료구조 활용', 5, '자료구조 활용이란 자료구조 유형별 특성을 고려하여 애플리케이션 구현과 정렬 및 탐색 알고리즘에 적합한 자료구조를 선정하여 활용하는 능력이다.'),
  ('2001020401_19v4', '20010204', 1, '데이터베이스 요구사항 분석', 6, '데이터베이스 요구사항 분석이란 데이터베이스를 설계하고 구현하기 위해 최종사용자의 요구사항을 수집, 분석하고 정의하며, 각 단계의 산출물에 대하여 검증하는 능력이다.'),
  ('2001020402_19v4', '20010204', 2, '개념데이터 모델링', 7, '개념데이터 모델링이란 비즈니스 도메인에 대한 데이터 주제영역을 분류하고 핵심개체, 식별자, 핵심속성, 핵심관계를 도출하여 개념 E-R 다이어그램으로 표현하고 검증하는 능력이다.'),
  ('2001020403_19v4', '20010204', 3, '논리 데이터베이스 설계', 6, '논리 데이터베이스 설계란 개념 데이터모델을 상세화 하여 비즈니스의 논리적인 데이터집합, 관리항목 및 관계 등 데이터 구조 및 규칙을 논리 E-R 다이어그램을 통해서 명확하게 표현하는 능력이다.'),
  ('2001020404_19v4', '20010204', 4, '물리 데이터베이스 설계', 6, '물리 데이터베이스 설계란 논리 데이터베이스 구조(스키마), 처리 요구 조건, 데이터베이스, 하드웨어, 운영 체제 특성을 기반으로 물리 데이터베이스의 저장 형식을 분석, 설계, 접근 경로를 물리적으로 설계하는 능력이다.'),
  ('2001020405_19v4', '20010204', 5, '데이터베이스 구현', 4, '데이터베이스 구현이란 설계된 데이터베이스 모델을 적용하기 위해 DBMS를 설치하고 데이터베이스와 데이터베이스 오브젝트를 생성하는 능력이다.'),
  ('2001020406_16v3', '20010204', 6, '데이터 품질관리', 5, '데이터 품질관리란 정보시스템 구축 시 데이터베이스 사용자 기대수준의 품질을 확보하기 위해 정책을 수립하고, 데이터 품질을 진단하고 개선하는 능력이다.'),
  ('2001020408_19v4', '20010204', 8, '데이터베이스 성능확보', 6, '데이터베이스 성능확보란 성능 상의 문제점을 분석하고 성능개선 목표를 설정하며 성능개선 수행 방법의 정의, 성능개선 수행, 성능개선 결과를 정량적으로 평가하며, 각 단계별 산출물 및 수행 활동을 규정하는 능력이다.'),
  ('2001020409_16v3', '20010204', 9, '데이터 표준화', 4, '데이터 표준화란 데이터베이스 설계와 구축 시에 필요한 데이터 정보 요소의 명칭, 정의, 형식, 규칙에 대한 정책을 수립하여 적용하는 능력이다.'),
  ('2001020411_19v4', '20010204', 11, '데이터 전환 설계', 6, '데이터 전환설계란 원천의 데이터베이스, 파일, 문서로부터 목적 데이터베이스 구축에 필요한 데이터를 추출하고 목적 시스템의 데이터 모델에 적합하게 변환, 정제하기 위한 계획을 수립하고 설계하는 능력이다.'),
  ('2001020412_19v4', '20010204', 12, '데이터 전환', 5, '데이터 전환이란 원천의 데이터베이스, 파일, 문서로부터 목적 데이터베이스 구축에 필요한 데이터를 추출하고 목적 시스템의 데이터 모델에 적합하게 변환, 정제하여 목적 데이터베이스에 적재한 후 그 결과를 검증하여 운영 가능한 데이터베이스를 구축하는 능력이다.'),
  ('2001020413_19v4', '20010204', 13, 'SQL활용', 3, 'SQL활용이란 관계형 데이터베이스에서 SQL을 사용하여 목적에 적합한 데이터를 정의하고, 조작하며, 제어하는 능력이다.'),
  ('2001020414_19v4', '20010204', 14, 'SQL응용', 5, 'SQL응용이란 관계형 데이터베이스에서 SQL을 사용하여 응용시스템의 요구기능에 적합한 데이터를 정의하고, 조작하며, 제어하는 능력이다.'),
