  (136, 6, '11~12주차', '데이터 품질 검수(QA) 및 오류 분석·수정'),
  (136, 7, '13~14주차', '프로젝트 운영 지원(데이터 관리, 문서 작성, 작업 현황 관리 등) 및 실무 협업'),
  (136, 8, '15~16주차', '프로젝트 운영 지원, 실습 결과 정리, 종합 피드백 및 성과 평가'),
  (137, 1, '1~2주차', '기업 및 브랜드 소개, 조직문화와 BD 직무에 대한 이해를 바탕으로 실습 목표를 바탕으로 업무 프로세스를 학습 / 중국 패션 시장 및 주요 플랫폼(Douyin, Xiaohongshu 등)의 구조와 특징을 이해하고, 시장조사 및 데이터 정리 방법 지도'),
  (137, 2, '3~4주차', '중국 패션 셀러, KOL, 라이브커머스 채널, 유통사 등을 조사하며 시장조사 및 데이터 수집 실무를 수행 / 조사한 데이터를 정리하고 리서치 결과를 공유'),
  (137, 3, '5~6주차', '리서치 결과를 기반으로 협업 가능성이 있는 파트너를 선정하고 우선순위를 설정하여 비즈니스 제안 대상 리스트를 구축 / 다양한 플랫폼(DM, 이메일)을 활용하여 커뮤니케이션을 진행'),
  (137, 4, '7~8주차', '선정된 파트너를 대상으로 컨택하고, 회신 관리 및 미팅 일정 조율 진행 / 커뮤니케이션 진행 현황을 체계적으로 관리하며 업무 진행 과정을 기록하고 실무 피드백을 반영'),
  (137, 5, '9~10주차', '컨택 결과를 분석하여 리포트를 작성하고 시장 반응 및 협업 가능성을 분석 / 담당 프로젝트를 자율적으로 수행하며 신규 파트너 발굴과 시장조사를 직접 계획하고 실행'),
  (137, 6, '11~12주차', '수행 결과를 점검하고 실무 관점에서 개선사항을 도출하여 커뮤니케이션 완성도를 높임 / toomuchtax 브랜드 운영 보조 및 업무 진행'),
  (137, 7, '13~14주차', '다양한 타깃군을 대상으로 시장조사 및 비즈니스 제안을 수행하며 업무 숙련도를 향상 / 기존 리서치 데이터를 고도화하고 신규 시장 및 협업 기회를 발굴하여 BD 전략을 보완'),
  (137, 8, '15~16주차', '실습 기간 동안 수행한 프로젝트를 종합 정리하고 협업 성과 및 리서치&컨택 결과를 분석하여 최종 리포트를 작성 및 공유'),
  (138, 1, '1~2주차', '회사 및 통역사업부 소개, 통역 프로젝트 전체 흐름 교육 / 직장 내 기본 예절, 업무 보고 방식, 문서 작성 및 행정 실무 교육 / 통역사 DB 구조, 실적자료 관리 방식, Excel 데이터 정리 방법 교육 / 기존 프로젝트 사례 열람 및 통역 프로젝트 진행 단계 정리'),
  (138, 2, '3~4주차', '통역사 배정 기준 및 일정 관리 원칙 교육 / 통역사 일정 관리 및 배정 업무 보조 / 수출상담회 실적 데이터 집계 및 정리 실습 / BIS@T 등 내부 시스템 또는 관련 데이터 관리 방식 이해 / 실적자료 오류 검토 및 수정 보조'),
  (138, 3, '5~6주차', '통역사 교육 및 사전자료 전달 프로세스 교육 / eQQui 플랫폼을 활용한 통역사 검색, 후보자 정리, 매칭 보조 / 통역 프로젝트 진행 상황 확인 및 운영 지원'),
  (138, 4, '7~8주차', '통역 프로젝트 진행 지원 업무 수행 / 통역 프로젝트 운영 보조 / 실적자료 오류 검토 및 수정 보조'),
  (138, 5, '9~10주차', '통역 프로젝트 운영 단계별 업무 흐름 심화 이해 / 통역사 관리 자료 업데이트 및 프로젝트별 통역사 배정 이력 정리 / 프로젝트 종료 후 결과자료 정리 방식 교육'),
  (138, 6, '11~12주차', '수출상담회 및 통역 프로젝트 운영 지원 업무 심화 수행 / 통역사 리스트 정비 및 언어별·분야별 인력풀 분류 보조 / 프로젝트 운영 중 발생한 이슈와 대응 방식 사례 정리'),
  (138, 7, '13~14주차', '통역 프로젝트 마감 및 정산 프로세스 교육 / 통역사 운영 데이터 및 실적자료 최종 점검 / 실습 기간 중 수행한 업무 결과물 정리'),
  (138, 8, '15~16주차', '실습 수행 업무 종합 정리 / 통역 프로젝트 운영 프로세스 개선 의견 작성 / 실습 결과 피드백 면담'),
  (139, 1, '1~2주차', '담당 직무 내용 교육 및 도면숙지 교육'),
  (139, 2, '3~4주차', '안전진단 장비 종류 및 사용방법 교육'),
  (139, 3, '5~6주차', '안전진단 현장조사 자료 정리 체계 교육'),
  (139, 4, '7~8주차', '안전진단 도면 작성 체계 교육'),
  (139, 5, '9~10주차', '안전진단 보고서 작성 체계 교육'),
  (139, 6, '11~12주차', '안전진단 자료정리, 도면, 보고서 작성'),
  (139, 7, '13~14주차', '안전진단 자료정리, 도면, 보고서 작성'),
  (139, 8, '15~16주차', '안전진단 자료정리, 도면, 보고서 작성'),
