INSERT INTO review_alert (id, institution_id, job_id, kind, field_key, description, source_document_id, page_a, quote_a, page_b, quote_b) VALUES
  (1, 4, 116, 'LIST_MISMATCH', 'majorRequirement', '선호 전공: 참여기관 리스트는 인문, 사회계열, 운영계획서는 전공 무관', 4, 4, '전공무관 3명', NULL, NULL),
  (2, 6, NULL, 'DOC_INCONSISTENCY', NULL, '교육목표의 대상 전공은 컴퓨터공학인데, 학생요건의 전공은 소프트웨어학과로 서로 다르다.', 6, 2, '*본 인턴십은 컴퓨터공학 전공 학생들이 실제 산업 현장에서 요구되는 소프트웨어 개발 역량과', 2, '소프트웨어학과 (1명)'),
  (3, 9, NULL, 'DOC_INCONSISTENCY', NULL, '1~2쪽 직무의 운영/지도계획은 16주차(15~16주차)까지 있으나 실습기간은 2026년 9월 1일~12월 12일로 약 15주여서 계획 주차와 기간이 맞지 않는다.', 9, 2, '2026년 9월 1일 ~ 2026년 12월 12일', 3, '* 15~16주차: 제작한 콘텐츠 및 소스 정리 후 마무리'),
  (4, 9, 130, 'LIST_MISMATCH', 'majorRequirement', '선호 전공: 참여기관 리스트는 글로벌비즈니스어학부, 경영학부, 광고홍보콘텐츠학과, 운영계획서는 전공 무관', 9, 3, '무관 (1인)', NULL, NULL),
  (5, 9, 131, 'LIST_MISMATCH', 'majorRequirement', '선호 전공: 참여기관 리스트는 글로벌비즈니스어학부, 경영학부, 광고홍보콘텐츠학과, 운영계획서는 전공 무관', 9, 5, '무관 (1인)', NULL, NULL),
  (6, 16, 138, 'LIST_MISMATCH', 'stipendAmount', '실습지원비: 참여기관 리스트는 1,617,660원, 운영계획서는 1,700,000원', 16, 2, '[1,700,000]원', NULL, NULL);
